const fs = require("fs");
const API = "http://localhost:9000";
const FAC = "f4d48e7c-f66a-4b6b-8b1b-c9e06c88a022";
const GEO = "b7efeebc-763f-4478-9849-5e6e55a043e6";
const DEPT = "01390617-ceb3-4257-8603-43243c3e1888";

async function main() {
  const state = JSON.parse(fs.readFileSync("tests/.auth/user.json","utf8"));
  const ls = state.origins[0].localStorage;
  const refresh = ls.find(e=>e.name==="care_refresh_token").value;
  const r = await fetch(`${API}/api/v1/auth/token/refresh/`, {method:"POST", headers:{"Content-Type":"application/json"}, body: JSON.stringify({refresh})});
  const {access, refresh: newRefresh} = await r.json();
  fs.writeFileSync("/tmp/care_token.txt", access);
  const aidx = ls.findIndex(e=>e.name==="care_access_token"); ls[aidx].value = access;
  if (newRefresh) { const ridx = ls.findIndex(e=>e.name==="care_refresh_token"); ls[ridx].value = newRefresh; }
  fs.writeFileSync("tests/.auth/user.json", JSON.stringify(state, null, 2));

  const headers = {"Authorization": `Bearer ${access}`, "Content-Type": "application/json"};

  async function createPatient(name) {
    const res = await fetch(`${API}/api/v1/patient/`, {method:"POST", headers, body: JSON.stringify({
      name, gender: "male", phone_number: "+91" + Math.floor(9000000000 + Math.random()*99999999),
      date_of_birth: "1985-05-05", identifiers: [], geo_organization: GEO
    })});
    const d = await res.json();
    if (!res.ok) throw new Error("patient create failed: " + JSON.stringify(d));
    return d.id;
  }

  async function createEncounter(patientId, status, encounter_class) {
    const res = await fetch(`${API}/api/v1/encounter/`, {method:"POST", headers, body: JSON.stringify({
      patient: patientId, facility: FAC, organizations: [DEPT],
      status, encounter_class, priority: "routine",
      period: {start: new Date().toISOString()}, tags: []
    })});
    const d = await res.json();
    return {ok: res.ok, status: res.status, d};
  }

  const pid = await createPatient("Restart Test Patient");
  console.log("patient", pid);

  const completedTry = await createEncounter(pid, "completed", "amb");
  console.log("create-as-completed:", completedTry.status, JSON.stringify(completedTry.d).slice(0,300));

  if (!completedTry.ok) {
    // fallback: create in_progress then update to completed
    const enc = await createEncounter(pid, "in_progress", "amb");
    console.log("create-in_progress:", enc.status);
    const encId = enc.d.id;
    const updateRes = await fetch(`${API}/api/v1/encounter/${encId}/`, {method:"PUT", headers, body: JSON.stringify({
      status: "completed", encounter_class: "amb", priority: "routine",
      period: {start: enc.d.period.start, end: new Date().toISOString()},
      external_identifier: null, discharge_summary_advice: null
    })});
    const updateD = await updateRes.json();
    console.log("update-to-completed:", updateRes.status, JSON.stringify(updateD).slice(0,300));
    var finalEncId = encId;
  } else {
    var finalEncId = completedTry.d.id;
  }

  console.log("final encounter id:", finalEncId);

  const restartRes = await fetch(`${API}/api/v1/encounter/${finalEncId}/restart/`, {method:"POST", headers, body: "{}"});
  const restartD = await restartRes.json();
  console.log("restart attempt:", restartRes.status, JSON.stringify(restartD).slice(0,500));
}
main().catch(e=>console.error("ERR", e));
'
