{"filePath": "/Users/rithviknishad/ohc.network/care_docs/recordings/support/prepPatient.ts", "content": "import { faker } from "@faker-js/faker";
import { expect, type Page } from "@playwright/test";

import { getFacilityId } from "./care";

// Mirrors care_fe/tests/facility/patient/patientRegistration.spec.ts's
// fillAdditionalDetails: the geo-org comboboxes cascade, so keep selecting the
// last one that appears until no new level shows up.
async function fillAdditionalDetails(page: Page): Promise<void> {
  const addressBox = page.getByRole("textbox", { name: "Address" });
  if (!(await addressBox.isVisible().catch(() => false))) {
    await page.getByRole("button", { name: "Additional Details" }).click();
  }
  await addressBox.fill(faker.location.streetAddress());
  await page
    .getByRole("spinbutton", { name: "PIN Code" })
    .fill(`${faker.number.int({ min: 1, max: 9 })}${faker.string.numeric(5)}`);

  const geoRegion = page.getByRole("region", { name: "Additional Details" });
  let previousCount = 0;
  for (;;) {
    const comboboxes = geoRegion.getByRole("combobox");
    const count = await comboboxes.count();
    if (count === previousCount) break;

    await comboboxes.nth(count - 1).click();
    await page.getByRole("option").first().click();
    previousCount = count;

    try {
      await geoRegion
        .getByRole("combobox")
        .nth(count)
        .waitFor({ state: "visible", timeout: 3000 });
    } catch {
      break;
    }
  }
}

/**
 * Registers a throwaway patient off camera, landing on that patient's home page.
 * Specs that mutate encounter state use this instead of the shared fixture patient,
 * so parallel specs never collide and the fixture patient never exceeds the
 * 5-open-encounters limit.
 */
export async function createIsolatedPatient(page: Page): Promise<void> {
  const facilityId = getFacilityId();
  await page.goto(`/facility/${facilityId}/patient/create`);

  await page
    .getByRole("textbox", { name: /name.*\*/ })
    .fill(faker.person.fullName());
  await page
    .getByRole("textbox", { name: /phone number.*\*/ })
    .fill(`${faker.helpers.arrayElement([7, 8, 9])}${faker.string.numeric(9)}`);
  await page.getByRole("radio", { name: "Male", exact: true }).click();

  await page
    .getByPlaceholder("DD", { exact: true })
    .fill(faker.number.int({ min: 1, max: 28 }).toString().padStart(2, "0"));
  await page
    .getByPlaceholder("MM", { exact: true })
    .fill(faker.number.int({ min: 1, max: 12 }).toString().padStart(2, "0"));
  await page
    .getByPlaceholder("YYYY", { exact: true })
    .fill(faker.number.int({ min: 1960, max: 2005 }).toString());

  await page.getByRole("combobox", { name: /blood group/i }).click();
  await page.getByRole("option").first().click();

  await fillAdditionalDetails(page);

  await page.getByRole("button", { name: /register patient/i }).click();
  await expect(
    page
      .locator("li[data-sonner-toast]")
      .getByText(/patient registered successfully/i),
  ).toBeVisible({ timeout: 15000 });
  await page.waitForURL(/\/patients\/home/);
}

/**
 * Creates an encounter for the patient on the currently open patient home page.
 * Must run after createIsolatedPatient. Returns the new encounter's id and patient id.
 */
export async function createIsolatedEncounter(
  page: Page,
  options: {
    encounterClass: string;
    status?: "In Progress" | "Planned" | "On Hold";
  },
): Promise<{ patientId: string; encounterId: string }> {
  await page.getByRole("button", { name: "Create Encounter" }).click();
  await page
    .getByRole("button", { name: options.encounterClass, exact: true })
    .click();

  if (options.status) {
    await page.getByRole("combobox", { name: "Status" }).click();
    await page.getByRole("option", { name: options.status, exact: true }).click();
  }

  await page.getByRole("tab", { name: "All Organizations" }).click();
  await page
    .getByRole("combobox")
    .filter({ hasText: "Select Department" })
    .click();
  await page.getByRole("option").first().click();

  await page.getByRole("button", { name: "Create Encounter" }).last().click();
  await expect(page.getByText("Encounter created successfully")).toBeVisible();
  await page.waitForURL(/\/encounter\/[^/]+\/updates/);

  const match = page
    .url()
    .match(/\/patient\/([^/]+)\/encounter\/([^/]+)\/updates/)!;
  return { patientId: match[1], encounterId: match[2] };
}
"}

