import { getPatientHomeUrl, saveRecording } from "../../support/care";
import { installCursor, Pointer } from "../../support/pointer";

// Records "How to Create an Encounter" from the patient page entry point, on the
// shared fixture patient. Creating an encounter never mutates an existing one, so
// this is safe to run against the shared fixture alongside the other specs.
const PAUSE = 900;

test("How to Create an Encounter", async ({ page }) => {
  const patientHomeUrl = await getPatientHomeUrl();
  await installCursor(page);
  const pointer = new Pointer(page);

  await test.step("1. Open the encounter form", async () => {
    await page.goto(patientHomeUrl);
    const createEncounter = page.getByRole("button", {
      name: "Create Encounter",
    });
    await expect(createEncounter).toBeVisible();
    await pointer.reset();
    await page.waitForTimeout(PAUSE);
    await pointer.click(createEncounter);
    await expect(
      page.getByRole("heading", { name: "Initiate Patient Encounter" }),
    ).toBeVisible();
    await page.waitForTimeout(PAUSE);
  });

  await test.step("2. Complete the form", async () => {
    await pointer.click(page.getByRole("button", { name: "Ambulatory" }));
    await page.waitForTimeout(PAUSE);

    // Departments is required — the submit button stays disabled until one is picked.
    await pointer.click(page.getByRole("tab", { name: "All Organizations" }));
    await pointer.click(
      page.getByRole("combobox").filter({ hasText: "Select Department" }),
    );
    await pointer.click(page.getByRole("option").first());
    await page.waitForTimeout(PAUSE);
  });

  await test.step("3. Save the encounter", async () => {
    await pointer.click(
      page.getByRole("button", { name: "Create Encounter" }).last(),
    );
    await expect(
      page.getByText("Encounter created successfully"),
    ).toBeVisible();
  });

  await page.waitForTimeout(2500);

  await saveRecording(
    page,
    "Clinical/Encounter/media/1. Create an Encounter.mp4",
  );
});
