import { expect, test } from "@playwright/test";

import { getFacilityId, saveRecording } from "../../support/care";
import { installCursor, Pointer } from "../../support/pointer";
import {
  createIsolatedEncounter,
  createIsolatedPatient,
} from "../../support/prepPatient";

// Records "How to Manage the Encounter Care Team" on its own encounter, so adding and
// removing a member never collides with another spec.
const PAUSE = 900;
const TEST_USERNAMES = ["care-doctor", "admin"];
const TEST_ROLES = [
  "Primary healthcare service",
  "Acupuncturist",
  "Orthotist and prosthetist",
];

test("How to Manage the Encounter Care Team", async ({ page, context }) => {
  const facilityId = getFacilityId();
  const selectedUsername = faker.helpers.arrayElement(TEST_USERNAMES);
  const selectedRole = faker.helpers.arrayElement(TEST_ROLES);

  // --- Unrecorded prep: isolated patient with an active encounter ---
  const prepPage = await context.newPage();
  await createIsolatedPatient(prepPage);
  const { patientId, encounterId } = await createIsolatedEncounter(prepPage, {
    encounterClass: "Ambulatory",
    status: "In Progress",
  });
  await prepPage.close();
  // --- End of unrecorded prep ---

  const encounterUrl = `/facility/${facilityId}/patient/${patientId}/encounter/${encounterId}/updates`;
  await installCursor(page);
  const pointer = new Pointer(page);

  await test.step("1. Open the care team sheet", async () => {
    await page.goto(encounterUrl);
    await expect(page.getByRole("tab", { name: "Overview" })).toBeVisible();
    await pointer.reset();
    await page.waitForTimeout(PAUSE);

    await pointer.click(page.getByRole("tab", { name: "Actions" }));
    await pointer.click(page.getByRole("button", { name: "Manage Care Team" }));
    await expect(
      page.getByRole("dialog", { name: "Manage Care Team" }),
    ).toBeVisible();
    await page.waitForTimeout(PAUSE);
  });

  await test.step("2. Add a member", async () => {
    const dialog = page.getByRole("dialog", { name: "Manage Care Team" });

    await pointer.click(
      dialog.getByRole("combobox").filter({ hasText: "Select Department" }),
    );
    await pointer.click(page.getByRole("option").first());
    await page.waitForTimeout(PAUSE);

    const memberSelector = dialog
      .getByRole("combobox")
      .filter({ hasText: "Select Member" });
    await pointer.click(memberSelector);
    await pointer.type(page.getByPlaceholder("Search"), selectedUsername);
    await pointer.click(
      page.getByRole("option", { name: selectedUsername }).first(),
    );
    await page.waitForTimeout(PAUSE);

    await pointer.click(
      dialog.getByRole("combobox").filter({ hasText: "Select Role" }),
    );
    await pointer.type(page.getByPlaceholder("Select Role"), selectedRole);
    await pointer.click(page.getByRole("option", { name: selectedRole }));
    await page.waitForTimeout(PAUSE);

    await pointer.click(dialog.getByRole("button", { name: "Add" }));
    await expect(page.getByText("Member added successfully")).toBeVisible();
    await page.waitForTimeout(PAUSE);
  });

  await test.step("3. Set the primary member", async () => {
    const dialog = page.getByRole("dialog", { name: "Manage Care Team" });
    await pointer.click(
      dialog.getByRole("button", { name: "Mark as Primary" }).first(),
    );
    await expect(
      page.getByText("Primary member updated"),
    ).toBeVisible();
    await page.waitForTimeout(PAUSE);
  });

  await test.step("4. Remove a member", async () => {
    const dialog = page.getByRole("dialog", { name: "Manage Care Team" });
    await pointer.click(dialog.getByRole("button", { name: "Remove" }).first());
    await expect(
      page.getByRole("dialog", { name: "Confirm Removing Member" }),
    ).toBeVisible();
    await page.waitForTimeout(PAUSE);

    await pointer.click(
      page
        .getByRole("dialog", { name: "Confirm Removing Member" })
        .getByRole("button", { name: "Remove" }),
    );
    await expect(
      page.getByText("Member removed successfully"),
    ).toBeVisible();
  });

  await page.waitForTimeout(2500);

  await saveRecording(
    page,
    "Clinical/Encounter/media/4. Manage the Encounter care team.mp4",
  );
});
