const s=JSON.parse(fs.readFileSync('tests/.auth/user.json','utf8'));
const ls=s.origins.flatMap(o=>o.localStorage||[]);
const refresh=ls.find(x=>x.name==='care_refresh_token').value;
(async()=>{
  const r=await fetch('http://localhost:9000/api/v1/auth/token/refresh/',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({refresh})});
  const j=await r.json();
  const access=j.access;
  for(const o of s.origins) for(const e of (o.localStorage||[])) { if(e.name==='care_access_token') e.value=access; if(e.name==='care_refresh_token') e.value=j.refresh; }
  fs.writeFileSync('tests/.auth/user.json', JSON.stringify(s,null,2));
  const res = await fetch('http://localhost:9000/api/v1/tag_config/?resource=encounter&status=active&parent_is_null=true&limit=50',{headers:{Authorization:'Bearer '+access}});
  const data = await res.json();
  console.log('count', data.count);
  (data.results||[]).forEach(t=>console.log(t.id, t.display, 'has_children='+t.has_children));
})();
"", "explanation": "Refresh token, persist it, then query encounter tag config", "goal": "Determine available tag config for encounter resource and refresh stored token", "mode": "sync"}

